import{_ as o,o as d,c as t,a2 as c}from"./chunks/framework.BVc2lkLk.js";const u=JSON.parse('{"title":"设计决策记录","description":"QFlareBot 框架的核心设计决策与理由：为什么用 Cloudflare Workers、插件怎么隔离和构建。","frontmatter":{"description":"QFlareBot 框架的核心设计决策与理由：为什么用 Cloudflare Workers、插件怎么隔离和构建。"},"headers":[],"relativePath":"design.md","filePath":"design.md","lastUpdated":1790693945000}'),r={name:"design.md"};function i(s,e,n,l,a,p){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="设计决策记录" tabindex="-1">设计决策记录 <a class="header-anchor" href="#设计决策记录" aria-label="Permalink to &quot;设计决策记录&quot;">​</a></h1><p>这份文档记录框架的核心决策与理由，改动契约前先读它。最初写于 2026-09-18，之后随实现更新。</p><h2 id="_1-为什么是-cloudflare-workers" tabindex="-1">1. 为什么是 Cloudflare Workers <a class="header-anchor" href="#_1-为什么是-cloudflare-workers" aria-label="Permalink to &quot;1. 为什么是 Cloudflare Workers&quot;">​</a></h2><p>QQ 开放平台 Webhook 已不再要求 IP 白名单（在 <code>qqbot-cfworker</code> 原型中实测：回调验证、被动回复、连续回复、富媒体、单聊主动消息全部跑通）。Webhook 模式没有长连接、没有心跳，Worker 只在有事件时被唤醒，&quot;永久运行&quot;零成本。</p><h2 id="_2-语言与工具" tabindex="-1">2. 语言与工具 <a class="header-anchor" href="#_2-语言与工具" aria-label="Permalink to &quot;2. 语言与工具&quot;">​</a></h2><p>TypeScript + wrangler。Workers 是 JS 一等公民，WebCrypto/fetch 原生；Rust/Python 在此 I/O 密集场景无收益且生态不足。零第三方运行时依赖（Hono/zod 都没用），bundle 极小。</p><h2 id="_3-单-worker-触发构建自部署" tabindex="-1">3. 单 Worker，触发构建自部署 <a class="header-anchor" href="#_3-单-worker-触发构建自部署" aria-label="Permalink to &quot;3. 单 Worker，触发构建自部署&quot;">​</a></h2><p>一个 Worker 同时承担 bot 与管理面。装/卸插件不是它自己能完成的动作——Workers 里没有编译器，依赖解析更无从谈起——所以&quot;自我部署&quot;的实现是：<strong>Worker 改写 D1 里的插件清单，然后调用 Cloudflare Builds REST API 触发一次构建</strong>；构建机（Workers Builds）拉取本仓库源码与各插件源码，编译并部署。部署脚本（seed 的 <code>scripts/build-deploy.mjs deploy</code>）直接用构建产物走 Versions API：上传版本（不切流量）→ 打预览地址 <code>/healthz</code> → 切流量。</p><p>安全阀：</p><ol><li>部署走&quot;先上传后切流量&quot;，健康检查失败就不切。健康检查带 <code>?plugins=1</code>：新版本把每个插件都加载一遍，入口一加载就抛错的插件同样让这次不切流量（旧运行时忽略这个参数）。含 Durable Object 的 Worker 没有版本预览 URL（平台限制），此时跳过健康检查——这是当前最大的例外</li><li>插件用动态 <code>import()</code>，某个插件求值抛错只影响自己，面板照常可用（声明 Durable Object 的插件例外：类必须静态导出，随主模块求值，求值失败会拖垮整个 Worker）</li><li>声明 Durable Object 的插件在<strong>安装</strong>这一步就被拦下并给出要补的 <code>migrations</code>——投影对 DO 迁移只校验不合成（构建机没有「上次应用到哪个 tag」的持久状态），校验在构建阶段，不拦的话插件已入 D1 才炸，且此后每次构建都炸</li><li>快照里的 <code>safeMode</code> 跳过全部插件；Cloudflare 后台版本回滚、以及&quot;恢复 D1 清单快照 + 重新触发构建&quot;是最后手段</li><li>部署凭证不进 Worker：Worker 只持有 Builds 触发 token（user-scoped，权限仅触发构建与读构建状态）；编译与部署凭证由构建机持有</li></ol><p>代价与信任模型：插件代码与框架同 isolate、同 realm 无沙箱，permissions 声明只是&quot;知情同意&quot;，不是安全边界。这与 NoneBot/Koishi 的&quot;装的插件即可信代码&quot;前提一致，文档中说明并建议 bot 单开一个 Cloudflare 账号。</p><h2 id="_4-插件-源码分发-清单驱动-构建时编译" tabindex="-1">4. 插件：源码分发，清单驱动，构建时编译 <a class="header-anchor" href="#_4-插件-源码分发-清单驱动-构建时编译" aria-label="Permalink to &quot;4. 插件：源码分发，清单驱动，构建时编译&quot;">​</a></h2><p>Workers 没有可写文件系统，也禁止 <code>eval</code>，&quot;下载到本地再 import&quot; 不成立；Worker 内编译则受 CPU/体积限制且要自建依赖解析，同样不成立。因此插件以<strong>源码</strong>分发、在构建机编译：</p><ul><li><p><strong>插件是源码仓库</strong>（<code>git:&lt;owner&gt;/&lt;repo&gt;@&lt;commit&gt;[#&lt;子目录&gt;]</code>，只支持公开的 GitHub 仓库）。作者运行 <code>qqbot-plugin build</code> 生成 <code>dist/plugin.js</code> + <code>dist/manifest.json</code>，并把 <code>manifest.json</code> 作为<strong>声明文件提交进仓库</strong>——面板与安装器只读它（权限展示、撞名/依赖/冲突检测），永不执行插件代码。</p></li><li><p><strong>插件可以带第三方依赖，按插件自己的 lockfile 装</strong>。作者照常写 <code>dependencies</code>、提交 <code>package-lock.json</code> 或 <code>pnpm-lock.yaml</code>；构建机把源码解包在机器人仓库<strong>之外</strong>的临时目录，只装 <code>dependencies</code>（<code>npm ci --omit=dev --ignore-scripts</code>，pnpm 同理），打进插件自己的 <code>plugin.js</code>，各插件各带一份、版本互不影响。要点：</p><ul><li><strong>必须有 lockfile</strong>：没有的话同一个 commit 在不同时间会装出不同的代码，而每装一个别的插件都会重建全部插件，这个插件就可能被悄悄换掉，「钉在 commit 上」形同虚设。没有第三方依赖的插件不走安装，与以前完全一样。</li><li><strong>在仓库外构建</strong>：只解析得到插件自己声明、自己装的依赖。以前构建机解析的是机器人仓库里装着的包——版本不是作者锁定的那份，换一台机器人就构建不过。</li><li><strong>框架包一律用机器人仓库那一份</strong>：<code>@qqbot/sdk</code> 经 alias 指向机器人仓库，契约只有一个版本；其他 <code>@qqbot/*</code> 不许打进插件（会带进第二份运行时），<code>qqbot-plugin build</code> 在解析阶段就拦。</li><li><strong>不跑安装脚本、抽清单在去掉凭证的子进程里</strong>：抽清单要在 Node 里执行插件入口，插件和它依赖的顶层代码都会跑，构建机上又有凭证。装依赖和抽清单的子进程只带白名单里的环境变量（PATH、HOME、代理、npm 源等，名字像凭证的即使在白名单前缀里也剔掉）——以前是黑名单，<code>OPENAI_API_KEY</code>、<code>DATABASE_URL</code> 这类漏网。抽清单的子进程另外换一个一次性的 HOME，拿不到 npm 缓存、pnpm store 的位置：引导会打开 Workers Builds 的构建缓存，这两个目录会留到之后的构建（最多 7 天），插件往里写的东西就不只影响这一次；装依赖不执行插件代码，照旧用真实的 HOME、命中缓存。这仍不是沙箱（文件系统照样碰得到），信任模型仍是「装的插件——连同它的依赖——就是可信代码」。</li><li>依赖必须能在 Workers 里跑（不依赖 Node 内置模块、不用 <code>eval</code>）；体积与初始化耗时算在全机器人共享的 CPU / 内存里。</li></ul></li><li><p><strong>安装 / 升级 / 卸载 = 写 D1 清单 + 触发构建</strong>：<code>POST /admin/manifest/plugins</code> 校验声明清单（apiVersion、撞名、conflicts、depends、表前缀唯一性）后写入 D1 的 <code>rt_manifest_plugins</code>（连声明清单一起存，反向依赖、冲突、DO 类比对都靠它）；<code>DELETE /admin/manifest/plugins/:name</code> 做反向操作。<strong>两者都在写完清单后就地触发重建</strong>——只改 D1 不重建的话，插件还留在正在运行的 bundle 里，等于没生效。构建触发失败不回滚清单改动（清单已经改了，回滚只会更乱），如实报出来让用户手动重试。安装/升级/卸载/构建全程记录在 <code>rt_installs</code> 账本（清单哈希、build_uuid、commit、状态）。</p><p>一次改好几个（批量更新）时不必每个都构建：每个请求带 <code>build: false</code> 只写清单，最后调一次 <code>POST /admin/builds</code>。构建机拉的是最新清单，一次就全带上了；账本把触发之前的所有 pending 记录都并进这次构建（不按哈希筛——批量写入时每条存的是写它那一刻的哈希）。反过来，改完之后 D1 已经和线上部署一模一样（撤掉的是还没上线的改动）就不再触发构建。</p><p>安装前的检查分两档：以前就拦的照旧拦（conflicts、表前缀撞车、依赖缺失，依赖也认 D1 里等构建的提供者）；同名换了仓库、覆盖内置插件、命令重名、已装插件声明与它冲突、升级新增权限，这些以前能装、现在照样能装，只作为 <code>warnings</code> 返回，面板在预检（<code>dryRun: true</code>，什么都不写）时摆出来让人确认。DO 只拦<strong>新增</strong>的类：以前有过的类 migrations 早就在仓库里了。</p><p>账本哈希的语义要说准：构建机是<strong>在构建那一刻</strong>从 <code>/admin/build-manifest</code> 拉当前清单并据此重建的，也就是「收敛到最新」，<strong>不是</strong>「必须等于触发时那一份」——否则并发装两个插件就会让第二次构建无故失败。所以它<strong>不阻断构建</strong>：<code>/admin/build-manifest</code> 会一并返回触发这次构建的账本记录（<code>pendingBuild</code>；构建机带上 <code>x-build-uuid</code> 时精确对上，不带时取最近一条进行中的），构建机发现「触发时的哈希」与「实际构建的哈希」不一致时在日志里显著告警，由人决定要不要再触发一次。这样既保留可追溯性，又不把正常并发变成构建失败。</p><p><strong>期望状态与线上状态分开看</strong>。D1 是期望状态，线上跑的是上一次成功构建的那一份，两者之间总有时间差（构建几分钟，还可能失败）。构建机给每个插件记下出处（D1 装的还是仓库内置的、原始 git 来源），投影进入口模块（不参与投影哈希），运行时据此回答「线上这一份是什么」。<code>GET /admin/manifest/plugins</code> 把两边对照：已上线、线上是另一份、根本没上线、卸载还没生效。没有出处信息的老部署照旧能用，只是判断不了「清单是否已与线上一致」。</p><p><strong>构建失败时线上保持上一次成功的版本</strong>，这是故意的；失败的条目会留在 D1 里，之后每次构建都会带上它、每次都失败，直到有人处理。所以构建机把每个插件都试着编一遍，把「哪个插件、为什么」经 <code>POST /admin/build-report</code> 报回来（只写错误信息，不改清单），面板的「未上线的改动」里列出这些条目：从没装上的直接卸载，升级失败的改回线上那一版。</p></li><li><p><strong>清单真相分层</strong>：框架版本（core/ui）与内置插件在仓库的 <code>qqbot.manifest.json</code>（git 管，diff/回滚免费）；已安装插件集在 D1（运行时可写、有账本）；两者在构建时合并（D1 同名覆盖内置插件；D1 条目总带着来源，只能替换、下架不了——要下架内置插件改 <code>qqbot.manifest.json</code>）。启用/禁用、按群生效范围、改配置仍是 KV 快照，不触发构建。</p></li><li><p><strong>构建时校验</strong>：构建机按 commit 拉 tarball、esbuild 就地打包，重新抽取清单并与声明清单比对，不一致即失败——防止声明与代码漂移。比对只在一处放宽：声明清单是作者当时的 SDK 生成的，框架后来新加的顶层字段它没有，这时抽取结果是空默认值（<code>[]</code> / <code>{}</code> / <code>false</code>）就算一致；<code>apiVersion</code> 不拦（声明的是最低要求，比抽出来的低是常态，只有更高才告警）。否则框架每加一个带默认值的字段，所有已装插件会同时构建失败，违背下文「框架升级不要求插件重新打包」。产物记 SRI 完整性；SDK 解析到固定的虚拟命名空间，同一组插件在哪台机器上构建产物都一样。</p></li><li><p>旧制品源（<code>npm:</code> / GitHub Release 的 <code>github:</code> / <code>url:</code>）投影器仍支持，属旧模型兼容，不再推荐。</p></li><li><p>Dynamic Workers（Worker Loader，付费版 beta）保留为<strong>不可信脚本</strong>场景的执行后端（如群管自定义脚本、LLM 生成代码），制品格式相同，但不是插件系统的基础。</p></li></ul><p>种子仓库的本地投影命令（<code>pnpm project</code>）与构建机（<code>manifest:prepare</code>）跑同一个投影库，产出一致（投影哈希相同），互不覆盖。</p><h2 id="_5-插件数据-前缀即所有权" tabindex="-1">5. 插件数据：前缀即所有权 <a class="header-anchor" href="#_5-插件数据-前缀即所有权" aria-label="Permalink to &quot;5. 插件数据：前缀即所有权&quot;">​</a></h2><p>三种存储都按插件名加前缀——KV 是 <code>p:&lt;名&gt;:</code>、R2 是 <code>p/&lt;名&gt;/</code>、D1 是表名 <code>p_&lt;名&gt;_</code>。KV 和 R2 的前缀在包装层拼键时强制，插件拿不到原始 binding；D1 过去只有 <code>db.table()</code> 给个建议值，<code>run/exec</code> 收裸 SQL，等于零约束。现在 SQL 里必须写 <code>{表名}</code> 占位，指向别处的表名一律抛错（<code>sqlite_master</code>、引号包名、库名限定、<code>ATTACH</code>/<code>PRAGMA</code> 都拦）。</p><p><strong>这不是安全边界</strong>，插件和运行时编译进同一个 Worker、同一个 JS realm，真要使坏绕得过去；<code>permissions</code> 同样只用于安装前展示。前缀强制要买的是另外两样东西：插件之间不会撞表或误删，以及——<strong>框架凭前缀才枚举得出一个插件建过哪些表</strong>。卸载能把数据清干净，唯一的前提就是这个；表名逃出命名空间的那部分数据，框架永远只能留成孤儿。</p><p>「不会撞表或误删」有个必须承认的前提：<code>tablePrefix</code> 把非字母数字一律换成 <code>_</code>，于是 <code>my-plugin</code> 与 <code>my_plugin</code> 落到<strong>同一个前缀</strong> <code>p_my_plugin_</code>。所以加了两道闸——安装时拒绝与已装插件同前缀的组合（409），卸载时若某张表同时匹配别的已知插件的前缀就跳过不删并回报 <code>skippedTables</code>。宁可留一条孤儿，也不能 <code>DROP</code> 掉邻居的表：那是不可逆的。</p><p>由此：</p><ul><li><strong>卸载的清理分两步</strong>：先调插件的 <code>onUninstall(ctx, { purgeData })</code>（趁它的代码还在这次部署里，重建之后就没机会了），再由框架按前缀兜底清理。钩子抛错不挡兜底——插件写坏了不该让数据永远清不掉。</li><li><strong>数据默认保留</strong>。卸载多半是不想要了，但误删不可逆。留下的数据在 <code>GET /admin/storage</code> 里列为孤儿（名字从 KV/R2 的键前缀反推，D1 的从 <code>rt_installs</code> 账本补），可以单独清掉。「默认删」和「管不了」之间的第三条路是「默认留但看得见」。</li><li><strong><code>onInstall</code> 的 <code>rt:installed:&lt;名&gt;</code> 标记无条件删掉</strong>。数据清了，重装必须重新建表；数据留着，<code>onInstall</code> 本来就要求幂等。留着标记的后果是重装后它静默不跑。</li><li><strong>卸载要在新版本上线后再收一次尾</strong>。卸载请求当场删标记、清数据，但重建完成前旧代码还在跑：冷启动的实例读不到标记会重跑 <code>onInstall</code>，把表建回来、把标记写回去——正好复现上一条要防的问题。所以卸载时记一条待清理（<code>rt_pending_cleanups</code>），等插件确实不在这份部署里了，由 Cron 再删一遍标记、按需再清一遍数据（连快照里的配置）。收尾之前又装回来就取消它。</li><li><strong>跨插件访问数据走 service，不走数据层</strong>。直读别人的表是隐形依赖：对方一卸载，消费者静默坏掉，框架看不见这层关系。<code>services</code> + <code>depends</code> 把依赖写进清单，安装时校验，面板上可见。</li><li><strong>共享的东西也走 service，不做框架级的共享变量</strong>。几个插件都要同一份 LLM 密钥、同一个出图地址，做法是一个插件持有配置、对外提供服务，其他插件依赖它。共享变量看着更省事，但它和服务是同一件事的两种做法，而服务给出去的是能用的功能而不是一个裸值：换服务商、加重试和限流只改一处，密钥也不用发给每个插件。框架只管把服务这条路修好（可选依赖、同名服务、只给声明者），不往核心里加功能。</li><li><strong>服务工厂每个请求调用一次</strong>，拿的是提供方自己的 ctx。这是契约的一部分：服务对象里不能存跨请求的状态，也不能做「别的插件来登记」式的接口（登记只活一个请求）。将来要做「一个插件收集许多插件的东西」（LLM 调其他插件的工具、菜单列出所有插件的功能），方向是允许同名服务由多个插件提供、调用方一次拿到全部，而不是登记，也不另做事件总线。</li></ul><h2 id="_6-契约稳定性规则" tabindex="-1">6. 契约稳定性规则 <a class="header-anchor" href="#_6-契约稳定性规则" aria-label="Permalink to &quot;6. 契约稳定性规则&quot;">​</a></h2><ol><li><strong>SDK 与 Runtime 分离</strong>：<code>@qqbot/sdk</code> 只有类型、<code>definePlugin</code>（恒等函数）与测试工具；插件 bundle 中不允许任何运行时 import，所有能力由注入的 <code>ctx</code>/<code>session</code> 提供。框架升级不要求插件重新打包。</li><li><strong>契约有版本</strong>（<code>apiVersion</code>），清单里写的是插件<strong>最低</strong>要求的版本：给插件新增能力（ctx 字段、SDK 导出）时递增，运行时接受不高于自己的。这样老插件在新框架上照常能装，用了新能力的插件装到老框架上在安装时就被拦下，而不是跑到那一行才报 &quot;is not a function&quot;——这是以后给契约加东西的前提。以前是「必须相等」，升一次版本所有已发布插件都装不上；老运行时仍按相等检查，遇到版本更高的新插件照样拒装，所以这个改动本身前后兼容。现在是 3（2 加了 <code>ctx.db.batch()</code> 和 <code>ctx.publicUrl</code>，3 加了 <code>session.isBotAdmin</code>、<code>session.quote</code>、<code>ctx.botAdmins</code>、<code>meetsPermission()</code> 和 <code>mentionedUsers()</code>；SDK 里的函数也算，因为构建插件时用的是机器人仓库里那一份 SDK），每一版加了什么记在 SDK 的 <code>API_VERSION</code> 注释里。真有破坏性变更时，旧契约的适配器是独立 compat 包，只在清单含旧插件时投影进 bundle。<code>coreRange</code> 从未检查过，已废弃。</li><li><strong>处理器只接收一个对象参数</strong>，返回值也是对象；加字段永远兼容。</li><li><strong>永远暴露原始层</strong>：<code>session.raw</code>、<code>ctx.api.raw()</code>。QQ 新增能力不必等框架发版。</li><li><strong>触发器与配置 schema 是数据</strong>（manifest / JSON Schema），面板与安装器不执行插件代码。</li><li><strong>能力优先做成服务</strong>（<code>services</code> / <code>depends</code> / <code>ctx.service()</code>），核心 API 只增不改，废弃走 major。</li><li>第一天就带 <code>botId</code>、<code>platform</code>，事件名带命名空间（<code>qq.group.at_message</code>）。</li><li>契约冻结点是 <code>definePlugin</code> 的入口形状与声明清单（manifest.json）；构建产物是瞬态产物，不作为分发契约，构建工具链版本随仓库 pin。</li></ol><h2 id="_7-durable-object-政策" tabindex="-1">7. Durable Object 政策 <a class="header-anchor" href="#_7-durable-object-政策" aria-label="Permalink to &quot;7. Durable Object 政策&quot;">​</a></h2><p>DO 按 128 MB × 活跃墙上时钟计费：一个被持续访问的 DO 一天约 11,000 GB-s，免费版每日额度 13,000 GB-s。因此<strong>核心主路径不碰 DO</strong>（验签、匹配、分发、回复只用 KV/D1）。对插件不做限制：可声明自定义 DO 类（投影时前缀重导出为 <code>P_&lt;插件&gt;_&lt;类&gt;</code> 并注册），框架负责成本可见与文档说明。</p><h2 id="_8-冲突处理" tabindex="-1">8. 冲突处理 <a class="header-anchor" href="#_8-冲突处理" aria-label="Permalink to &quot;8. 冲突处理&quot;">​</a></h2><ul><li>命令名：manifest 静态声明，安装时检测到重名给出警告（不拦），比较时不分大小写、多个空白算一个；运行时按 <code>priority</code> 排序，命令默认 <code>block: true</code></li><li>子命令：命令名带空格即子命令（<code>&#39;pixiv random&#39;</code>），同一条消息命中多个命令名时最长的胜出、跨插件也一样，短的不再参与；子命令权限不够也不退回父命令</li><li>同事件多处理器：priority + block（NoneBot 模型），快照可覆盖优先级</li><li>被动回复配额：<code>msg_seq</code> 由 Session 集中分配并设上限（默认 5）</li><li>存储：KV <code>p:&lt;name&gt;:</code> 前缀、D1 <code>p_&lt;name&gt;_</code> 表前缀由框架强制</li><li>依赖/互斥：manifest <code>depends</code> / <code>conflicts</code>；<code>depends</code> 的值写 <code>&#39;optional&#39;</code> 即可选依赖（写在值里而不是另开字段：老运行时只认键，把它当必需依赖，缺了拒装而不是装上之后出错）</li><li>同名服务：可以共存，同一时间只有一个在提供。默认先注册、且启用着的那个，面板上可以选（存快照 <code>serviceProviders</code>）；选了就不自动换人，被禁用时如实报错。以前是先注册的赢、后来的只在日志里提一句，用户看不见也改不了</li><li>服务只给声明者：<code>ctx.service()</code> 只认本插件 <code>depends</code> 里有的。服务表是整个请求共用的，以前不查这一条，别的插件先解析过、没声明的也能拿到——能不能用取决于谁先跑</li><li>HTTP 路由：统一挂 <code>/p/&lt;name&gt;/</code></li><li>Cron：框架只注册一个 Cron Trigger，按插件表达式分发（免费版 Trigger 仅 5 个）</li><li>全局篡改：同 isolate 无法禁止，靠构建期 lint 与审核</li></ul><h2 id="_9-面板与插件页面" tabindex="-1">9. 面板与插件页面 <a class="header-anchor" href="#_9-面板与插件页面" aria-label="Permalink to &quot;9. 面板与插件页面&quot;">​</a></h2><p>面板是 <code>@qqbot/ui</code>（Vue 3），构建产物内联进 Worker 制品由运行时返回——自我部署不需要额外的 Cloudflare API，UI 与管理 API 永远同版本。插件页面走<strong>解耦</strong>方案：插件路由返回任意 HTML，面板以 sandbox iframe 打开，<code>@qqbot/ui-bridge</code> 提供 token、主题与 postMessage 通道；不做&quot;插件写 Vue 组件挂进面板&quot;的原生扩展，避免把面板组件 API 变成公共契约。鉴权是无状态 HMAC 令牌（会话 7 天、桥接 1 小时且限定插件），轮换 <code>ADMIN_TOKEN</code> 即全部失效。详见<a href="./ui">面板与插件页面</a>，设计 token 见仓库里的 <a href="https://github.com/QFlareBot/QFlareBot/blob/main/design-system/qflarebot/MASTER.md" target="_blank" rel="noreferrer">design-system/qflarebot/MASTER.md</a>。</p><h2 id="_10-里程碑" tabindex="-1">10. 里程碑 <a class="header-anchor" href="#_10-里程碑" aria-label="Permalink to &quot;10. 里程碑&quot;">​</a></h2><p><strong>M1</strong>：sdk / api / runtime / projector / plugin-cli / 示例插件 / 种子应用 / 插件模板。平台能力覆盖见 <a href="./capabilities">平台能力对照</a>：按键（自动升级 markdown）、<code>buttons</code> 匹配器与交互自动 ack、event_id 被动回复、引用、视频/语音/文件、流式（单聊）、撤回、输入中、群管理。清单投影、多模块部署元数据与 Versions API 客户端也在这时实现，当时还没对线上实测，到 M2 跑通。</p><p><strong>M2</strong>：清单入 D1（<code>rt_manifest_plugins</code> + <code>rt_installs</code> 账本）、构建清单 API（<code>GET /admin/build-manifest</code>）、安装/卸载端点（声明清单校验、conflicts/depends 检测）、Builds API 触发与构建状态/commit 同步、seed 自部署脚本（git 源码构建 + Versions API 健康检查部署 + 仓库清单回退）、面板安装入口（粘贴仓库链接 + 构建记录列表）、插件数据所有权（D1 表名前缀强制、卸载清理、<code>GET /admin/storage</code> 存储视图，见第 5 节）。线上 Builds 已实测跑通（Versions API 上传 → 健康检查 → 切流量，<code>workers_dev: false</code> 下预览地址同样可用）。</p><p><strong>M2 之后（当前）</strong>：插件第三方依赖（按插件自己的 lockfile、在仓库外构建，见第 4 节）；批量更新只构建一次；构建失败回报与「未上线的改动」；期望状态与线上状态对照；插件目录 <a href="https://github.com/QFlareBot/plugins" target="_blank" rel="noreferrer">QFlareBot/plugins</a> 与面板「市场」（批量安装只构建一次）；插件前缀改为 <code>qflarebot-plugin-</code>（旧的 <code>qqbot-plugin-</code> 构建时照样认）。</p><p><strong>M3（计划）</strong>：多轮对话（<code>session.prompt</code>，Conversation DO）、<code>ctx.store(scope)</code> 通用 DO、构建日志内嵌面板、Access 集成指引、Dynamic Workers 脚本引擎插件。</p>',34)])])}const m=o(r,[["render",i]]);export{u as __pageData,m as default};
